import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 17 · daily recipe test (Vinicius, 2/11/2026): one Christmas recipe a day, Grandma Ruth's Kitchen
# The Christmas Fudge EVERYONE's Grandma Made (5 Minutes, No Thermometer Tricks)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, if you came to my house any December since nineteen sixty-five, you left with a little tin of fudge. Every neighbor, every teacher, the mailman, the pastor, the boy who shoveled the walk. One year I made fourteen batches. And people still stop me at church and ask, Ruth, how does yours come out so smooth, when mine turns to sand every time?""",
   "chocolate fudge squares Christmas tin", "FOURTEEN BATCHES")
sc("""So tonight I'm going to give you my Christmas fudge. Every ingredient, every step, and the three mistakes that turn fudge grainy, so you never make them. It takes about fifteen minutes and one pot, and it makes a whole nine by thirteen pan. Get your pencil, honey, and maybe a glass of milk, because you're going to want to taste it.""",
   "chocolate fudge pan kitchen", "ONE POT, FIFTEEN MINUTES")

ch("Where it came from")
sc("""When I was a girl, my mother made fudge the hard way. Sugar, milk, cocoa and butter in her heavy pot, boiled until a drop in a glass of cold water made a soft ball between her fingers. Then she beat it with a wooden spoon until her arm ached. Some years it was perfect. Some years it was like gravel, and my father ate it anyway and said it was the best she ever made.""",
   "1950s mother cooking kitchen stove", "LIKE GRAVEL")
sc("""Then in the nineteen sixties, a recipe started showing up on the back of the jars of marshmallow creme. People called it fantasy fudge. My mother tried it in nineteen sixty-four, the Christmas I turned twenty, and she never went back. The marshmallow keeps the sugar from making crystals, so it comes out smooth almost every time. That's the one I'm giving you.""",
   "vintage marshmallow creme jar kitchen", "SMOOTH EVERY TIME")

sc("""The first year I made it on my own was nineteen sixty-five, in my first little kitchen on Diamond Street, on a stove that ran hot on the left side. I burned the first batch black. The second batch I stood there with my eyes on the clock like a hawk, and it came out so smooth my husband ate a quarter of the pan before supper. That's when I learned the whole secret of this fudge is the clock.""",
   "1960s young woman kitchen stove", "THE SECRET IS THE CLOCK")

ch("What you need")
sc("""Here's what you need, honey. Three cups of white sugar. Three quarters of a cup of butter, that's a stick and a half. Two thirds of a cup of evaporated milk, from the can, not sweetened condensed milk. Remember that, they look alike on the shelf and they are not the same thing. One twelve ounce bag of semi-sweet chocolate chips. One seven ounce jar of marshmallow creme. And one teaspoon of vanilla.""",
   "baking ingredients sugar butter chocolate chips", "EVAPORATED, NOT CONDENSED")
sc("""For tools, you need a heavy three quart saucepan, a wooden spoon, and a nine by thirteen pan. Line the pan with foil or parchment, with the edges hanging over the sides like handles, and butter it. That way you lift the whole block out to cut it, and you don't dig it out of the corners with a knife. Grandma Pearl's pans had knife scratches all over the bottom from fifty years of fudge.""",
   "baking pan lined foil kitchen counter", "HANDLES ON THE FOIL")
sc("""And here's my first secret, sweetheart. Measure everything and open everything before you turn on the stove. Open the jar of marshmallow, open the chocolate chips, have the vanilla on the counter with the cap off. Once that sugar boils, you can't walk away for a single second, and you can't be fighting a jar lid with one hand.""",
   "ingredients measured bowls ready kitchen", "OPEN EVERYTHING FIRST")

ch("Step by step")
sc("""Step one. Put the sugar, the butter and the evaporated milk in the saucepan, over medium heat. Stir it all the time with the wooden spoon until the butter melts and the sugar dissolves. Rub a little between your fingers if you're not sure. If it feels gritty, keep stirring. That's important, because a grain of sugar that doesn't melt now becomes sand later.""",
   "saucepan stirring sugar butter stove", "NO GRIT")
sc("""Step two. Bring it to a full rolling boil. That means a boil you can't stir down. Big bubbles all over, even while you stir. Now look at the clock. Boil it for four minutes, stirring all the time, all the way to the bottom and into the corners so it doesn't scorch. If you have a candy thermometer, you want two hundred and thirty-four degrees. If you don't, four minutes at a full boil gets you there.""",
   "rolling boil candy saucepan", "FOUR MINUTES")
sc("""Step three. Take it off the heat. Right away, dump in the whole bag of chocolate chips and stir until they melt and it's all one shiny brown. Then add the marshmallow creme and the vanilla, and stir hard until there are no white streaks left. Your arm will get a little tired, honey. That's how you know you're doing it right.""",
   "melted chocolate stirring pot", "NO WHITE STREAKS")
sc("""Step four. Pour it into your pan right away, and smooth it out with the back of the spoon. Work fast, because it starts to set as soon as it cools. Then leave it alone on the counter, at room temperature, for at least four hours, or overnight. Don't put it in the icebox to hurry it. It sets better slow.""",
   "pouring fudge into pan", "IT SETS BETTER SLOW")

sc("""How do you know it's right, honey? When you stir it in the pan, it should look glossy, like wet paint, and the spoon should leave a little trail that slowly closes up. If it's already stiff and dull in the pot, you boiled it a little too long. Work fast and it will still be good. If it's thin and runs like syrup, it needed another minute. Next batch, you'll know.""",
   "glossy chocolate fudge spoon", "GLOSSY LIKE WET PAINT")

ch("Three mistakes that ruin it")
sc("""Now the three mistakes, sweetheart, because this is where most fudge goes wrong. Mistake one. Not boiling it long enough. If you take it off at two minutes because you got nervous, it never sets. You'll have chocolate sauce. Delicious on ice cream, but not fudge. Use a timer and trust the four minutes.""",
   "kitchen timer stove cooking", "TRUST THE FOUR MINUTES")
sc("""Mistake two. Scraping the sides of the pot when you pour. Up on the sides of the pot, sugar crystals have dried, and if you scrape them into the pan, they turn the whole batch grainy. Pour, and let what stays in the pot stay in the pot. That's the cook's treat, honey. I always gave the pot and the spoon to whoever was in the kitchen.""",
   "chocolate saucepan spoon licking", "DON'T SCRAPE THE POT")
sc("""Mistake three. Using the wrong milk or cheap chocolate. Sweetened condensed milk makes it too sweet and it won't set right with this recipe. And the cheapest store chocolate chips have wax in them, so the fudge looks dull and tastes like a candle. Buy good semi-sweet chips. It's the only thing in this recipe worth spending a little more on.""",
   "chocolate chips bag baking", "TASTES LIKE A CANDLE")

ch("Cutting and keeping")
sc("""When it's firm, lift it out by the foil handles and peel the foil off. Cut it with a big sharp knife dipped in hot water and wiped dry between every cut. That gives you clean, square edges like a candy store. Small squares, about an inch. Fudge is rich, honey. Nobody needs a piece the size of a brick, no matter what your grandson says.""",
   "cutting fudge squares knife board", "DIP THE KNIFE IN HOT WATER")
sc("""To keep it, layer the squares in a tin with wax paper between every layer, and keep the lid on tight. It stays good at room temperature for about two weeks, if it lasts that long. And it freezes beautifully, wrapped tight, for two or three months. I start my Christmas fudge right after Thanksgiving and freeze half of it, so I'm not cooking on the twenty-third.""",
   "fudge tin wax paper layers", "WAX PAPER BETWEEN LAYERS")

sc("""And a little warning from experience. Don't double this recipe in one pot. It sounds smart, but a double batch never boils evenly, the bottom scorches before the top is ready, and you end up with half a pan of fudge and a pot you'll be scrubbing until New Year's. If you need more, make two batches, one after the other. That's what I did, all fourteen of them.""",
   "two pots stove cooking candy", "NEVER DOUBLE IT")
sc("""And if your kitchen is humid, honey, or it's a rainy day, boil it thirty seconds longer. Sugar candy hates damp weather. My mother wouldn't make fudge on a rainy day at all. She'd look out the window in the morning and say, not today, and we'd make cookies instead.""",
   "rainy window kitchen vintage", "NOT ON A RAINY DAY")

ch("Make it yours")
sc("""Now a few ways to change it, once you've made the plain one. Stir in a cup of chopped walnuts at the end, that's how Grandma Pearl liked it. Or swap the vanilla for peppermint extract and sprinkle crushed candy canes on top while it's still soft. My grandchildren call that one the North Pole fudge. Or use peanut butter chips instead of chocolate for a peanut butter fudge that disappears in one afternoon.""",
   "peppermint fudge candy cane pieces", "NORTH POLE FUDGE")
sc("""And for gifts, sweetheart, you don't need fancy boxes. A clean jar with a square of red cloth tied over the lid. An old cookie tin from the thrift store. A paper plate covered in plastic wrap with a ribbon and a little card that says, made with love by Ruth. People don't remember the box. They remember that you made it.""",
   "homemade fudge gift tin ribbon", "THEY REMEMBER YOU MADE IT")

ch("Grandma's kitchen")
sc("""So here it is one more time. Sugar, butter and evaporated milk until there's no grit. A full rolling boil for four minutes. Chocolate, then marshmallow and vanilla, off the heat. Pour, don't scrape. Let it set slow. Cut with a hot knife. That's it, honey. Fifteen minutes, and you'll be the person everybody hopes is coming to the Christmas party.""",
   "chocolate fudge plate Christmas table", "FIFTEEN MINUTES")
sc("""Tell me in the comments, sweetheart. Do you like your fudge plain, with walnuts, or with peppermint? And what recipe should I make next? Every day I'm bringing you one recipe from my kitchen, the way my mother and Grandma Pearl made it. Good night, honey. Go make some fudge.""",
   "vintage kitchen warm light Christmas", "WHAT SHOULD I MAKE NEXT?")

for s in S:  # documentary look: four photos per scene and the six rotating camera moves
    s["cuts"], s["moves"] = 4, True

save("grandma17", "The Christmas Fudge EVERYONE's Grandma Made (Never Grainy, 5-Minute Boil)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Marshmallow creme 'fantasy fudge', a recipe popularized on US product labels in the 1960s.",
      "Recipe as written by Grandma Ruth: 3 cups sugar, 3/4 cup butter, 2/3 cup evaporated milk; full rolling boil 4 minutes (234 F); off heat add 12 oz semi-sweet chips, 7 oz marshmallow creme, 1 tsp vanilla; 9x13 pan; set 4 hours at room temperature."],
     "christmas with tips", minutes=(10, 14.5), voice="en_US-lessac-high")
